#include "devai/strategy/dev_ai_strategy/forecast/DevForecastMultiTimeframe_F3EF2C3.hpp"
#include "devai/strategy/dev_ai_strategy/forecast/DevForecastImproved_F3EF2C.hpp"
#include <filesystem>
#include <functional>
#include <iostream>
#include <map>
#include <set>
using namespace devai::forecast::f3ef2c3;
namespace fs=std::filesystem;
struct Quality{uint64_t n=0,correct=0,positive=0,eligible=0,eligible_wins=0;double sq=0,abs=0,base_sq=0,net=0,pred_sum=0;void add(double p,double y,double baseline,double close,double capital){++n;sq+=(p-y)*(p-y);abs+=std::abs(p-y);base_sq+=(baseline-y)*(baseline-y);pred_sum+=p;if((p>0)==(y>0))++correct;if(p>0)++positive;int qty=int(std::floor(capital*.75/close));if(qty<=0||p<=0)return;double buy=close,sell=close*(1+p);if(sell<=0)return;auto c=zerodha_nse(buy,sell,qty);if(p*close*qty<=c.total)return;++eligible;double realized_sell=close*(1+y);if(realized_sell<=0)return;double actual_net=(realized_sell-buy)*qty-zerodha_nse(buy,realized_sell,qty).total;net+=actual_net;if(actual_net>0)++eligible_wins;}double rmse()const{return n?std::sqrt(sq/n):0;}double baseline_rmse()const{return n?std::sqrt(base_sq/n):0;}};
struct Pick{double score=-1e100,actual=0;std::string symbol;};
struct Rank{Pick improved,old;};
int main(int argc,char**argv){try{
 if(argc!=7){std::cerr<<"Usage: "<<argv[0]<<" <F2C2_dir> <shares.txt> <F2C_model> <split_f3ef2.txt> <output_dir> <capital_INR>\n";return 2;}
 fs::path input=argv[1],out=argv[5];double capital=std::stod(argv[6]);if(!(capital>0))throw std::runtime_error("capital must be positive");fs::create_directories(out);
 std::ifstream split(argv[4]);if(!split)throw std::runtime_error("missing split manifest");std::string manifest((std::istreambuf_iterator<char>(split)),{});if(manifest.find("20260313")==std::string::npos||manifest.find("20260622")==std::string::npos)throw std::runtime_error("split manifest differs from frozen F2/F2C split");
 std::ifstream symbols(argv[2]);if(!symbols)throw std::runtime_error("cannot open symbols");std::vector<std::string> names;std::string name;std::set<std::string> seen;while(std::getline(symbols,name)){if(!name.empty()&&name.back()=='\r')name.pop_back();if(name.empty()||name[0]=='#'||name.find("NIFTY")!=std::string::npos)continue;if(!seen.insert(name).second)throw std::runtime_error("duplicate symbol");names.push_back(name);}if(names.empty())throw std::runtime_error("no symbols");
 constexpr int VAL=20260313,TEST=20260622;
 auto scan=[&](const std::function<void(const Row&)>&f){for(auto&sym:names){fs::path path=input/(sym+"_training_f3ef2c2.csv");std::ifstream in(path);if(!in)throw std::runtime_error("missing "+path.string());std::string line;std::getline(in,line);auto columns=header(line);uint64_t n=0;long long last=0;while(std::getline(in,line)){if(line.empty())continue;auto r=parse(line,columns);if(r.symbol!=sym)throw std::runtime_error("symbol mismatch");if(r.epoch<=last)throw std::runtime_error("non-monotonic timestamp");last=r.epoch;if(finite(r)){f(r);++n;}}std::cerr<<"READ "<<sym<<" rows="<<n<<'\n';}};
 Stats stats;std::array<double,5> sums{},counts{};scan([&](const Row&r){if(r.session>=VAL)return;stats.add(r.x);for(int h=0;h<5;++h)if(r.valid[h]&&std::isfinite(r.y[h])){sums[h]+=r.y[h];++counts[h];}});
 Model model;model.scale.fit(stats);for(int h=0;h<5;++h){if(!counts[h])throw std::runtime_error("empty training target");model.base[h]=sums[h]/counts[h];}
 std::array<Normal,5> norm;scan([&](const Row&r){if(r.session>=VAL)return;auto x=model.scale.apply(r.x);for(int h=0;h<5;++h)if(r.valid[h]&&std::isfinite(r.y[h]))norm[h].add(x,r.y[h]);});
 constexpr std::array<double,5> lambdas{1e-7,1e-5,1e-3,1e-2,1e-1};std::array<std::array<std::array<double,K+1>,5>,5> candidates{};for(int h=0;h<5;++h)for(int l=0;l<5;++l)candidates[h][l]=solve(norm[h],lambdas[l]);
 std::array<std::array<Metric,5>,5> validation{};scan([&](const Row&r){if(r.session<VAL||r.session>=TEST)return;auto x=model.scale.apply(r.x);for(int h=0;h<5;++h)if(r.valid[h]&&std::isfinite(r.y[h]))for(int l=0;l<5;++l)validation[h][l].add(predict(candidates[h][l],x),r.y[h],model.base[h]);});
 for(int h=0;h<5;++h){int best=0;for(int l=1;l<5;++l)if(validation[h][l].n&&validation[h][l].rmse()<validation[h][best].rmse())best=l;if(!validation[h][best].n)throw std::runtime_error("empty validation");model.lambda[h]=lambdas[best];model.w[h]=candidates[h][best];}
 model.save((out/"forward_forecast_f3ef2c3.model").string());
 // Read the frozen F2C model, with original 12 features, on exactly the same F2C2 held-out rows.
 std::ifstream oldfile(argv[3]);if(!oldfile)throw std::runtime_error("missing F2C model");std::string magic;oldfile>>magic;if(magic!="F3EF2C_RIDGE_V1")throw std::runtime_error("incorrect F2C model format");devai::forecast::f3ef2c::Model old;for(auto&x:old.scale.mean)oldfile>>x;for(auto&x:old.scale.sd)oldfile>>x;for(int h=0;h<5;++h){int hz=0;oldfile>>hz>>old.lambda[h]>>old.base[h];if(hz!=horizons[h])throw std::runtime_error("F2C horizon mismatch");for(auto&x:old.w[h])oldfile>>x;}if(!oldfile)throw std::runtime_error("truncated F2C model");
 std::array<Quality,5> fresh{},prior{};std::map<std::pair<long long,int>,Rank> ranking;
 std::ofstream detail(out/"heldout_predictions_f3ef2c3.csv");if(!detail)throw std::runtime_error("cannot write details");detail<<"symbol,decision_epoch,session_id,horizon_minutes,close,actual_return,f2c_predicted_return,f2c3_predicted_return,f2c3_predicted_net_inr,f2c3_realized_net_inr,f2c3_eligible\n"<<std::setprecision(14);
 scan([&](const Row&r){if(r.session<TEST)return;auto pp=model.predict(r);devai::forecast::f3ef2c::Row previous;previous.x.fill(0);for(int i=0;i<12;++i)previous.x[i]=r.x[i];auto oo=old.predict(previous);for(int h=0;h<5;++h){if(!r.valid[h]||!std::isfinite(r.y[h]))continue;double y=r.y[h];fresh[h].add(pp[h],y,model.base[h],r.close,capital);prior[h].add(oo[h],y,old.base[h],r.close,capital);
 int qty=int(std::floor(capital*.75/r.close));double predicted_net=0,actual_net=0;bool eligible=false;if(qty>0&&1+pp[h]>0&&1+y>0){double pred_sell=r.close*(1+pp[h]);predicted_net=pp[h]*r.close*qty-zerodha_nse(r.close,pred_sell,qty).total;eligible=pp[h]>0&&predicted_net>0;double actual_sell=r.close*(1+y);actual_net=y*r.close*qty-zerodha_nse(r.close,actual_sell,qty).total;}
 detail<<r.symbol<<','<<r.epoch<<','<<r.session<<','<<horizons[h]<<','<<r.close<<','<<y<<','<<oo[h]<<','<<pp[h]<<','<<predicted_net<<','<<actual_net<<','<<(eligible?1:0)<<'\n';
 auto& rk=ranking[{r.epoch,h}];if(pp[h]>rk.improved.score)rk.improved={pp[h],y,r.symbol};if(oo[h]>rk.old.score)rk.old={oo[h],y,r.symbol};}});
 std::ofstream metrics(out/"comparison_metrics_f3ef2c3.csv");metrics<<"horizon_minutes,model,test_rows,rmse,baseline_rmse,mae,directional_accuracy,positive_forecast_fraction,mean_predicted_return,lambda,eligible_count,eligible_mean_realized_net_inr,eligible_win_fraction\n"<<std::setprecision(14);
 for(int h=0;h<5;++h)for(int which=0;which<2;++which){const auto&q=which?prior[h]:fresh[h];double n=q.n?double(q.n):1,el=q.eligible?double(q.eligible):1;metrics<<horizons[h]<<','<<(which?"F2C_12_FEATURES":"F2C3_24_FEATURES")<<','<<q.n<<','<<q.rmse()<<','<<q.baseline_rmse()<<','<<q.abs/n<<','<<q.correct/n<<','<<q.positive/n<<','<<q.pred_sum/n<<','<<(which?old.lambda[h]:model.lambda[h])<<','<<q.eligible<<','<<q.net/el<<','<<q.eligible_wins/el<<'\n';}
 std::array<double,5> sumnew{},sumold{};std::array<uint64_t,5> rankcount{},wins{};for(auto&[key,r]:ranking){int h=key.second;if(r.improved.symbol.empty()||r.old.symbol.empty())continue;++rankcount[h];sumnew[h]+=r.improved.actual;sumold[h]+=r.old.actual;if(r.improved.actual>r.old.actual)++wins[h];}
 std::ofstream ranks(out/"top1_ranking_f3ef2c3.csv");ranks<<"horizon_minutes,decision_minutes,mean_realized_top1_f2c3,mean_realized_top1_f2c,improved_top1_win_fraction\n"<<std::setprecision(14);for(int h=0;h<5;++h){double n=rankcount[h]?double(rankcount[h]):1;ranks<<horizons[h]<<','<<rankcount[h]<<','<<sumnew[h]/n<<','<<sumold[h]/n<<','<<double(wins[h])/n<<'\n';std::cout<<"horizon="<<horizons[h]<<"m new_rmse="<<fresh[h].rmse()<<" old_rmse="<<prior[h].rmse()<<" eligible_new="<<fresh[h].eligible<<" eligible_old="<<prior[h].eligible<<'\n';}
 std::cout<<"F3E-F2C.3 COMPLETE symbols="<<names.size()<<" train_rows="<<stats.n<<" output="<<out<<"\n";
 }catch(const std::exception&e){std::cerr<<"F3E-F2C.3 ERROR: "<<e.what()<<'\n';return 1;}}
